draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.stroke();

  // Draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-70);
  ctx.stroke();

  // Applying wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('1849', W/2, H/2-200 + 20*Math.sin(t));

  ctx.restore();
}
